inputs.expression:
(
    /* Rename the mitre analysis key to mitre */
    $renameMitre := function($obj) {
        $obj ? $obj ~> | $ | { "mitre": $."ai-mitre-analysis" }, ["ai-mitre-analysis"] | : {}
    };
    /* Get raw results */
    $mitre_analysis := actions.AI_SOC_Hero_AI_MITRE_Analysis.result.published ;
    $mitre_results := ($mitre_analysis and $type($mitre_analysis) = "object") ? $mitre_analysis
    : ($mitre_analysis and $type($mitre_analysis) = "array" and $type($mitre_analysis[0]) = "object") ? $mitre_analysis[0]
    : {} ;

    $mitre_renamed := {
        "JSON_Object": {"ai-mitre-analysis":$renameMitre($mitre_results."ai-mitre-analysis"), "mitre-techniques-changed":"False"},
        "ai-mitre-analysis": $renameMitre($mitre_results."ai-mitre-analysis"),
        "mitre-techniques-changed":"False"
    };
    $mitre_renamed
)
